//! The output and input types ([`types`]), their schema ids ([`ids`]), and the registry behind `enth schema`.
//!
//! `enth schema <name>` prints the JSON Schema (draft 2020-12, generated by `schemars` from the Rust type) with
//! `$id` set to the schema id and `properties.schema.const` pinned to it, so a validator rejects an object of
//! another version. There is no `jsonschema` crate: its default features build C code. The typed round trip in the
//! tests keeps the schemas honest instead.

pub mod types;

use schemars::JsonSchema;
use schemars::generate::SchemaSettings;
use serde_json::Value;

pub use types::*;

/// The schema id of every object, `enth.<name>/<version>`. A shape change or a change of meaning bumps the
/// version (AGENTS.md).
pub mod ids {
    /// `enth schema`.
    pub const SCHEMA: &str = "enth.schema/1";
    /// `enth modules`.
    pub const MODULES: &str = "enth.modules/1";
    /// `enth params`.
    pub const PARAMS: &str = "enth.params/1";
    /// `enth new`.
    pub const NEW: &str = "enth.new/1";
    /// `enth new --list`.
    pub const TEMPLATES: &str = "enth.templates/1";
    /// `enth apply`.
    pub const APPLY: &str = "enth.apply/1";
    /// `enth get`.
    pub const GET: &str = "enth.get/1";
    /// `enth diff`.
    pub const DIFF: &str = "enth.diff/1";
    /// `enth render`.
    pub const RENDER: &str = "enth.render/1";
    /// `enth describe`.
    pub const DESCRIBE: &str = "enth.describe/1";
    /// `enth check`.
    pub const CHECK: &str = "enth.check/1";
    /// `enth step`.
    pub const STEP: &str = "enth.step/1";
    /// `enth guide`.
    pub const GUIDE: &str = "enth.guide/1";
    /// `enth bench`.
    pub const BENCH: &str = "enth.bench/1";
    /// Every error.
    pub const ERROR: &str = "enth.error/1";
    /// A performance (`--perf`, the WAV chunk).
    pub const PERF: &str = "enth.perf/1";
    /// The `enth` chunk of a WAV.
    pub const WAVMETA: &str = "enth.wavmeta/1";
    /// A patch file.
    pub const PATCH: &str = "enth.patch/1";
    /// The ops JSON.
    pub const OPS: &str = "enth.ops/1";
}

/// One schema `enth schema` can print.
pub struct Entry {
    /// The name given to `enth schema`.
    pub name: &'static str,
    /// The schema id.
    pub id: &'static str,
    /// What it describes.
    pub describes: &'static str,
    /// Generates the JSON Schema.
    pub generate: fn() -> Value,
}

fn gen_schema<T: JsonSchema>() -> Value {
    SchemaSettings::draft2020_12()
        .into_generator()
        .into_root_schema_for::<T>()
        .to_value()
}

