/// The entry named `name` (a name such as `check`, or an id such as `enth.check/1`).
pub fn entry(name: &str) -> Option<&'static Entry> {
    let n = name.trim();
    ENTRIES.iter().find(|e| e.name == n || e.id == n)
}

/// The JSON Schema of an entry: generated, with `$id` and the `schema` field pinned to the id.
pub fn json_schema(e: &Entry) -> Value {
    let mut v = (e.generate)();
    if let Value::Object(m) = &mut v {
        m.insert("$id".to_owned(), Value::from(e.id));
        if let Some(Value::Object(props)) = m.get_mut("properties")
            && let Some(Value::Object(field)) = props.get_mut("schema")
            && field.get("type") == Some(&Value::from("string"))
        {
            field.insert("const".to_owned(), Value::from(e.id));
        }
    }
    v
}
